"A 6×30 m strip of haze pushes units, jetpacks and even projectiles; direction changes every 2 minutes. Autumn.":"6×30m의 아지랑이 띠가 유닛, 제트팩, 심지어 투사체까지 밀어낸다. 방향은 2분마다 바뀐다. 가을.",
