"A meadow of steel dandelions: fluff sticks and corrodes armour −2/s, jumps to neighbours on contact.":"강철 민들레 군락. 솜털이 달라붙어 장갑을 초당 2씩 부식시키며, 접촉하면 이웃에게 옮겨 간다.",
"A rootstock with vines: barely moves, lashes everyone nearby (damage and knockback).":"덩굴 달린 뿌리줄기. 거의 움직이지 않으며 주변 모두를 덩굴로 후려친다(피해와 넉백).",
"Hit it from range — beyond its aggro radius it is harmless.":"멀리서 공격하라. 어그로 반경 밖에서는 무해하다.",
