"Rockets, grenades, fire.":"로켓, 수류탄, 화염.",
"A three-legged hunter: get close and it chases you and claws, gives up after 20 s.":"세 발 달린 사냥꾼. 가까이 가면 쫓아와 발톱으로 공격하며, 20초 뒤 포기한다.",
"Keep your distance or escape by jetpack.":"거리를 유지하거나 제트팩으로 도망쳐라.",
"A rootstock on root legs: burrows (a dust mound moves underground, invulnerable), surfaces under its target and tosses it.":"뿌리 다리를 가진 뿌리줄기. 땅속으로 파고들어(먼지 더미가 지하로 이동, 무적) 목표 아래에서 솟구쳐 위로 날려 버린다.",
