"Emerald grass, spores, crystals: the grass hides infantry beyond 40 m until it fires. Verdans live here.":"에메랄드빛 풀, 포자, 크리스탈. 풀이 보병을 숨겨 준다. 40m 밖에서는 사격하기 전까지 보이지 않는다. 베르단이 살고 있다.",
