"Three modes — one button":"세 가지 모드 — 버튼 하나",
"Ladder":"단계",
"Strategist → Commander → Shooter: one mode button (PC Tab/P, phone — top button, gamepad — View; hold to pick).":"전략가 → 지휘관 → 사격수: 모드 버튼 하나로 전환합니다(PC는 Tab/P, 휴대폰은 상단 버튼, 게임패드는 View. 길게 누르면 셋 중에서 선택).",
"Pause: Esc / ☰ / Menu. Help: F1 in battle, full key list \"/\". Clean screen F9.":"일시정지: Esc / ☰ / Menu. 도움말: 전투 중 F1, 전체 키 목록은 \"/\". 클린 스크린 F9.",
"Mode":"모드",
"Top view: building, production, group orders, CP support. LMB select, RMB order; on phone — taps and the build panel.":"탑뷰 시점: 건설, 생산, 그룹 명령, 지휘 포인트(CP) 지원. 좌클릭으로 선택, 우클릭으로 명령. 휴대폰에서는 탭과 건설 패널을 사용합니다.",
"Buildings: Z X C V B N K · v8.0 groups on the right · ":"건물: Z X C V B N K · v8.0 그룹은 오른쪽 · ",
"Tilted camera over your squad: click to move, on an enemy to attack, 1–4 abilities, Tab next squad, double-click a trooper to dive into the shooter.":"분대 위에서 내려다보는 기울어진 카메라. 클릭하면 이동, 적을 클릭하면 공격, 1–4는 능력, Tab은 다른 분대, 병사를 더블클릭하면 사격수 모드로 뛰어듭니다.",
"Camera: Q/E, wheel, WASD, Space — back to squad.":"카메라: Q/E, 휠, WASD, Space — 분대로 복귀.",
"First-person combat as any trooper or vehicle. Jetpack, slide, grenade, rocket, reflex, artillery, rifle-butt melee.":"어떤 병사나 차량으로든 1인칭 전투. 제트팩, 슬라이딩, 수류탄, 로켓, 리플렉스, 포격, 개머리판 근접 공격.",
"Phone: left joystick to move, right half to look, buttons on the right.":"휴대폰: 왼쪽 조이스틱으로 이동, 오른쪽 화면으로 시점 조작, 버튼은 오른쪽에 있습니다.",
