"Also: wrecks of destroyed enemies, first-expedition depots and crystals (shoot them) give one-off ore.":"그 외: 파괴된 적의 잔해, 1차 원정대 보급 창고, 크리스탈(사격하면)이 일회성 광석을 준다.",
