"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"새로운 광석 외형: 광맥이 검은 현무암 위에서 빛나는 에메랄드빛 각진 크리스탈이 되고 불꽃과 녹색 안개가 더해졌어; 추출기는 육각 받침대, 벌집 돔, 꼭대기에 녹색 신호등이 있는 격자 탑 (줄무늬와 깃발은 팀 색상)",
"New in v6.1":"v6.1 신규",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"배틀필드식 선호 병과 (U, 사망 후 숫자): 가능하면 해당 병과로 리스폰해",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"장비 1인칭 시점 (V — 외부/조종석); 가벼운 에임 어시스트 — 설정에서",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"코어에서 쉽게 탈출: 스페이스 — 수직갱으로, B — 지표로 캡슐; 능력 효과는 사망 시 초기화",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"끝없는 성장: 장군과 원수 ★, 캠페인 레벨, 무기 숙련과 부착물, 훈장, 일일 계약 — 캠페인 화면",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"전략: 휠로 부드러운 줌, 유닛 위 아이콘과 이름표(Alt — 전체), 왼쪽에 병력 / 건물 패널",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"우클릭 — 이동 중 교전, 우클릭 두 번 — 이동 중 사격하며 행군; 드문 명령은 \"추가 명령 ▾\"에; 버튼은 중복되지 않음",
"New in v6":"v6 신규",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"슈터급 사격: 즉발 탄환, 분당 720발 소총, 기관총, 반동, 우클릭 조준, 탄창과 R 재장전, 적중 표시",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"더 무거운 중력, 반응 빠른 제트팩, Z 또는 공중에서 제트팩 두 번으로 대시; 다른 유닛으로 전환해도 무기가 따라오지 않음",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"건설병: 건설병 선택 → 건물 선택 → 설계도 배치; 광석 광맥에 추출기 설치; \"광석\"을 클릭하면 수입 출처와 증가 방법 확인",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"회색 버튼은 이유를 설명하고 해결책을 제안; 더 큰 버튼, \"진행 중\" 줄, \"▶ 빙의\", Tab은 하나의 모드 키",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"튀거나 뒤집히지 않는 전략 카메라, 커서 방향 줌, 미니맵 드래그 가능",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"신규 장비: \"자칼\" 습격차, \"그라드\" 다연장로켓(유도 로켓), \"해머\" 박격포; 스웜은 \"말벌\", \"벌집\", \"투석기\" 추가",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"전략가가 명령을 유지하고 음성 남발을 멈춤; 전투가 너를 찾아옴; B — 재배치, Shift+B — 전투 속으로; 나침반, H — 어느 목표",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"자유 행동(K)과 단독 행동(J), F2 프리셋; Esc로 일시정지와 재개; 저장: 슬롯, 파일 내보내기와 불러오기",
"New in v5.3":"v5.3 신규",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"비행: 운석에서 멀수록 중력 강화, 공중에서 C로 제동, 추력 조향이 더 날카로움; 포털에 끼는 현상 해결",
"New in v5":"v5 신규",
"Endless war by default and battle scale: normal, large, epic":"기본값은 무한 전투, 전투 규모: 보통, 대규모, 대서사",
