"Intel: a Swarm squad is heading your way — {0}, about {1} meters.":"정찰: 스웜 분대가 이쪽으로 접근 중 — {0}, 약 {1}미터.",
"Contact from above! A Swarm pod is coming down {0}, {1} meters!":"위에서 접촉! 스웜 포드가 {0}에 낙하 중, {1}미터!",
"Swarm signaller {0}! It will call a drop in 12 seconds — kill it first!":"스웜 신호병 {0}! 12초 후 강하를 요청한다 — 먼저 처치해!",
