"🛠 Developer mode: everything unlocked, endless ore. Arsenal — F8 or the \"🛠 Arsenal\" button.":"🛠 개발자 모드: 전부 해금, 무한 광석. 무기고 — F8 또는 \"🛠 무기고\" 버튼.",
"Developer mode off (the match stays flagged — career is not saved)":"개발자 모드 꺼짐 (매치에는 표시가 남으며 캠페인은 저장되지 않는다)",
"Battle saves are disabled in developer mode":"개발자 모드에서는 전투 저장이 비활성화된다",
