"Boost":"가속",
"Scan":"스캔",
"Rockets":"로켓",
"Drones":"드론",
"Follow":"추적",
"Attack":"공격",
"Patrol":"순찰",
"Rally":"집결",
"Apply":"적용",
"Target locked":"목표 고정됨",
"AUTO: locks the nearest enemy and fires by itself; stick — circle around, swipe — next target":"자동: 가장 가까운 적을 고정하고 알아서 사격; 스틱 — 주위를 선회, 스와이프 — 다음 목표",
"AUTO off — normal look with gentle aim assist":"자동 꺼짐 — 기본 시점, 약한 조준 보조",
"Rocket reloading":"로켓 재장전 중",
"No grenades":"수류탄 없음",
"Grenade — at the target":"수류탄 — 목표로",
"Rocket — at the target":"로켓 — 목표로",
"Selected all of this type on screen":"화면 안의 같은 유닛을 모두 선택함",
