"Tap \"Aim\" to zoom in. Tap again to zoom out.":"\"조준\"을 탭하면 확대돼. 다시 탭하면 원래대로 돌아가.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"분대가 널 따라와. ☰ → \"일시정지\" → \"분대 동행\" 타일을 열어 — \"단독 행동\"으로 바뀌어.",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"건설병이 선택됐어 — 아래 카드의 \"◆ 크리스탈 채굴\"을 탭해 (또는 초록색 크리스탈을 탭).",
"Training complete!":"훈련 완료!",
"steps":"단계",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"이제 기지를 짓고, 병력을 주문하고, 지휘하고, 전투에 뛰어들 수 있습니다. 다음은 진짜 매치입니다: 안내자가 플레이 중에 도와줄 거예요.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"이제 이동하고, 날고, 사격하고, 엄폐하고, 분대를 지휘할 수 있습니다. 다음은 진짜 매치입니다.",
