"Again":"다시",
"done":"완료",
"you are on PC: keyboard and mouse":"PC를 쓰고 있어요: 키보드와 마우스",
"you are on a phone: touch screen":"휴대폰을 쓰고 있어요: 터치스크린",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"안전한 샌드박스: 적은 아직 가만히 서 있는 더미고, 아무도 당신을 쏘지 않습니다. 직접 행동했을 때만 단계가 인정됩니다.",
"Show others (training for the other device)":"다른 모드 보기 (다른 기기용 훈련)",
"Old training (v7.1)":"이전 훈련 (v7.1)",
"Back to the normal device mode":"기본 기기 모드로 되돌리기",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"다른 기기용 훈련을 선택하면 해당 모드로 페이지가 다시 시작됩니다 (PC — 마우스와 키보드, 휴대폰 — 터치. PC에서는 Chrome의 F12 → 휴대폰 아이콘으로 터치를 테스트할 수 있어요).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"훈련 ×4: PC용과 휴대폰용으로 나뉜 단계별 \"전략\"과 \"슈터\" 강의. 허수아비가 있는 안전한 샌드박스, 필요한 버튼 강조, 화살표, 애니메이션 키·마우스·제스처, 실제로 행동해야만 단계 완료, \"단계 반복\", 상단 진행도, 마지막 보상",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"훈련 메뉴에는 네 기기에 맞는 강의가 자동으로 표시됩니다. \"다른 모드 보기\"를 누르면 어떤 기기에서든 네 개 모두 볼 수 있고, \"이전 훈련 (v7.1)\"도 그대로 남아 있어요",
"New in v7.2":"v7.2 새 기능",
"NEW IN v7.2":"v7.2 새 기능",
"No grenades left":"수류탄이 떨어졌어요",
"Rocket and grenade recharging · {0} s":"로켓과 수류탄 충전 중 · {0}초",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"왼쪽 — 이동, 오른쪽 — 시점 · 적 탭 — 로켓 / 수류탄 · 2번 탭 — 리플렉스 · 3번 탭 — 포격",
"Less":"줄이기",
"More":"늘리기",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"근처에 적 차량이나 건물이 있어요 — 탭하면 로켓이 발사됩니다.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"적이 많아요 — 오른쪽 빈 곳을 빠르게 2번 탭하세요. 리플렉스가 시간을 늦춥니다.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"적이 몰린 곳에 조준하고 3번 탭하면 포격이 시작됩니다.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"왼쪽 손가락 — 이동, 오른쪽 손가락 — 시점. 적을 조준하면 자동으로 사격합니다.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"왼쪽 가장자리의 ⇑ — 제트팩: 탭하면 점프, 누르고 있으면 비행.",
"Old v7.2 layout":"이전 v7.2 배치",
"Drag a finger on the right half of the screen — a look stick appears under it.":"화면 오른쪽 절반에서 손가락을 끌면 그 아래에 시점 스틱이 나타납니다.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"왼쪽을 터치하고 밀면 손가락 아래에 스틱이 나타납니다. 초록색 표시까지 가세요.",
"Hold the \"Jet\" button at the left edge.":"왼쪽 가장자리의 \"제트팩\" 버튼을 누르고 있으세요.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"오른쪽 스틱으로 허수아비를 조준하세요. 조준점이 닿으면 보병이 알아서 사격합니다.",
"Tap the dummy on the screen — a rocket flies.":"화면에서 허수아비를 탭하면 로켓이 발사됩니다.",
"Tap the dummy — a grenade flies in an arc, right at it.":"허수아비를 탭하면 수류탄이 포물선을 그리며 날아갑니다 (목표 명중).",
"Double tap an empty spot on the right quickly.":"오른쪽 빈 곳을 빠르게 2번 탭하세요.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"저사양 휴대폰용 라이트 모드: 해상도 낮춤, 그림자·왜곡 없음, 봇과 입자 절반, 30 FPS 제한. FPS가 25 미만이면 해상도를 자동으로 낮춥니다. 휴대폰에서는 기본으로 켜져 있어요 (설정 → 그래픽 → \"라이트 모드\", 또는 링크에 ?lite=1 / ?lite=0).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"휴대폰: 새 조작 방식. 왼쪽 — 이동, 오른쪽 — 시점 (두 스틱 모두 손가락 아래에 나타남). 왼쪽 손가락만 쓰면 \"자동\", 오른쪽도 쓰면 조준점이 적에게 있을 때만 보병이 자동 사격합니다. 적 탭 — 로켓 또는 수류탄, 2번 탭 — 리플렉스, 3번 탭 — 포격. 자동 재장전. 제트팩은 왼쪽 가장자리 버튼. 아래쪽 모서리는 비어 있고, 미니맵은 모서리에, 힌트는 X로 닫을 수 있으며 목표는 접을 수 있어요. 이전 배치: 설정 → 휴대폰.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"힌트(팝업과 안내자)는 설정의 스위치 하나로 조절합니다. 지금 플레이 중인 대상(보병 또는 차량 종류)은 HUD의 \"당신: …\" 표시로 확인하세요. 소총과 기관총 조준경은 투명합니다. \"무기고\" 패널은 오른쪽에 고정되며 접거나 끌 수 있어요. \"분대 없이 단독\"(J)은 삭제되었습니다. 전략가 음성이 같은 대사를 반복하지 않아요. 전차에 포탑·차체 방향 표시가 생겼습니다. 전략 훈련을 시작할 때 커서가 사라지던 문제를 고쳤어요.",
