"Combo ×{0} · reflex +{1}%":"콤보 ×{0} · 리플렉스 +{1}%",
"Strategist: troopers dropping to you — +{0} (−{1} ore)":"전략가: 강하 병력이 당신에게 이동 중 — +{0} (−{1} 광석)",
"Hold on, sending troopers your way":"버텨요, 강하 병력을 보냅니다",
"· basic{0}":"· 기본{0}",
"· advanced":"· 고급",
"· rare":"· 희귀",
