"Voice of hints & curator":"힌트 및 안내자 음성",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"휴대폰: 스틱 모드 세 가지. 왼쪽만 — \"자동\" (강한 자석, 약한 탄). 오른쪽만 — 조준이 자동으로 켜지고 자석이 더 강하며 명중률이 높아요. 둘 다 — 조준 없음, 자석과 명중률 낮음. 오른쪽의 👁 버튼으로 HUD를 숨기거나 되돌릴 수 있어요.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"휴대폰: 전략이 단순화되어 공병과 건물만 다룹니다. 왼쪽 카드(공병, 사령부, 병영…)를 탭하면 카메라가 그쪽으로 이동하고, 아래 바에 바로 지을 것/생산할 것이 표시됩니다. \"전투 시작\"은 왼쪽 위에 있어요. 군대는 알아서 싸웁니다. 전체 전략은 설정 → 휴대폰.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"빙의 — 스위치 두 개: \"분대\"와 \"차량\" (휴대폰에서는 차량이 기본으로 꺼져 있으며 AI가 운전합니다). 차량이 꺼져 있을 때 아군 차량 옆에서 E(휴대폰은 오른쪽 버튼)를 누르면 포를 잡습니다. 차량은 알아서 달리고 당신은 사격해요. 기존의 병종 순서 직접 지정은 \"고급\"에 있습니다. 빙의하면 유닛이 무전으로 응답해요.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"스마트 힌트: 기본 힌트는 2번째 실행 후 자동으로 꺼지지만, 한 번도 쓰지 않은 기능은 게임이 알려줍니다. 스위치: 기본 / 고급 / 희귀, 그리고 힌트·안내자 음성 전용 스위치가 따로 있어요.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"리플렉스는 처치로 충전됩니다 (연속 처치는 더 많이). 동료가 뒤처지거나 전사하면 전략가가 새 병력을 당신에게 강하시킵니다 (일반 증원보다 비쌈). v7.2gfx 그래픽과 사운드가 통합되었습니다: 뭉게뭉게 피어오르는 폭발, 연기, 잔해, 갱도와 크레이터 음향. 빌드 날짜가 이제 실제 날짜예요.",
