"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"하늘은 포털입니다: 위로 날아가면 운석의 반대편으로 나오게 됩니다.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"전략가의 명령을 따르세요 — 명령 수행 시 경험치가 2배, 3배가 됩니다.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — 전투와 가장 가까운 분대나 차량으로 즉시 전환합니다.",
"Bullets hit hardest at medium range, 20–50 meters.":"탄은 20~50미터의 중거리에서 가장 강력합니다.",
"To win, destroy the Swarm HQ and all its key buildings.":"승리하려면 스웜 본부와 모든 핵심 건물을 파괴하세요.",
