"strategist bot left, shooter bot right":"왼쪽 전략가 봇, 오른쪽 슈터 봇",
"Cinema: everything built":"시네마: 모두 건설",
"both bases built and upgraded — for footage":"양쪽 기지 건설·업그레이드 완료 — 촬영용",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"시네마 모드 — 분할 화면: 왼쪽은 전략가 봇(기지와 군대 탑뷰), 오른쪽은 1인칭 슈터 봇입니다. 아래 버튼(키 S, P): \"분할 화면\"과 \"★ 모두 건설\" — 촬영용으로 양쪽 기지를 건설하고 업그레이드합니다.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"코어와 운석을 관통하는 터널은 사라졌다 — 운석은 통짜이고, 전투는 지표에서만 벌어진다.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"폰: 👁은 HUD를 숨기지만 제트팩, ⇆, 스틱, 목표 마커는 남겨 둔다. \"◎ 조준\"(오른손 손가락 전용) — 훨씬 강하고 넓은 자석 보정. 세 모드의 자석 세기는 설정 → 조작 → \"고급\"에서 바꾼다. 차량 포좌에서는 버튼이 \"내리기\"로 바뀐다.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"훈련: 폰에서는 폰용 훈련만, PC에서는 PC용만 표시된다. 4개 모두 \"🛠 개발자\" 메뉴에 있다. 개발자 모드와 무기고는 이제 하나의 메뉴다(전투 중에는 오른쪽 위 \"🛠 메뉴\", PC는 F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"그래픽 스타일 \"Dendy(8비트)\"와 \"16비트\": 설정 → 그래픽 → \"그래픽 스타일\"(자세한 설명은 ⚙ 버튼). 매치 시작 후 약 10초 동안 FPS가 24 미만이면 Dendy가 자동으로 켜진다(20 미만이 계속되면 픽셀이 더 커지고 120라인). \"일반으로 되돌리기\" 알림을 누르면 일반 그래픽이 영구 복원된다. 메뉴에서 직접 고른 설정이 항상 우선한다.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D 환경 모델(폐허, 잔해, 방어 시설) — 평가가 좋은 것만 필요할 때 스트리밍으로 불러온다. 끄기: 설정 → 그래픽 → \"새 3D 환경 모델\".",
"New in v7.5":"v7.5 새 소식",
"NEW IN v7.5":"v7.5 새 소식",
