"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"보병 건설: 아군 건설 현장에서 E(폰은 \"진입\") — 보병이 직접 짓고, 근처 분대원이 돕는다. 공병이 바쁘면 전략가가 \"건설 현장\" 마커로 도움을 요청한다.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"전략가 마커: 전략가가 근처 적 밀집 지점에 ⌖를 찍으면 8초 후 포격이 떨어지고, 가까운 아군 다연장 \"그라드\"가 일제 사격을 한다. 전략가 모드에서 직접 쓰는 포격도 \"그라드\" 지원을 받는다.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"화물 컨테이너와 추락한 위성 속 무기 상자(📦, 70 m부터 보임): E — 90초간 중기관총, 소이탄 또는 로켓, 그리고 수류탄 보충. 포복: Ctrl — 엎드리기 / 일어서기(더 낮고 안정적인 조준, 대신 느림).",
