"Link copied":"링크를 복사했다",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ 바로 플레이\" — 메뉴의 첫 번째 버튼: 포털 하늘 아래를 잠깐 날아간 뒤 곧장 전투로(아무 키나 탭으로 건너뛰기).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"타격감이 살아 있다: 금속성 소리와 불꽃, 조준점의 처치 마커(헤드샷은 노란색), ×N 연속 처치, 폭발의 부드러운 흔들림, 주요 처치 시 슬로모션. 흔들림, 슬로모션, 힌트는 설정에서 끌 수 있다.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"매치 결과: 시간, 처치 수, 최고 연속 처치, ★ MVP와 최고의 분대, 매치 카드 — \"⇪ 공유\", PNG 또는 게임 링크.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"자원 아래 왼쪽에 \"지금 할 일\" 힌트: 전략가의 명령, 점령할 지점, 스웜의 공세. ✕ 또는 F7 — 접기.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"탭을 닫거나 숨기면 전투가 자동 저장된다 — 메뉴의 \"⟲ 계속하기\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"새 버전이 마음에 안 들면 쓸 수 있도록 v7.5는 \"🕘 게임 버전\" 메뉴에 남아 있다. 이제 익명 통계(이름·이메일 없음)가 전송된다. 설정에서 끌 수 있다.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"바로 플레이\", 타격 피드백, 공유 카드가 있는 매치 결과, \"할 일\" 힌트, 자동 저장",
"and older: v7.5, v7.4, milestones v1–v7.0":"그리고 이전: v7.5, v7.4, 이정표 v1–v7.0",
"New in v7.6":"v7.6 새 소식",
"NEW IN v7.6":"v7.6 새 소식",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"매치 전 진영 선택: \"컨소시엄\"(동력 장갑을 두른 중보병, 장갑과 포병) 또는 \"스웜\"(속도, 드론 무리, 왜곡을 일으키는 강력한 사격). AI가 반대편을 맡는다. 선택은 저장된다.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"컨소시엄은 전차 \"코뿔소\"와 \"세라마이트 장갑판\", 스웜은 \"드론 무리\"와 \"위상 제트팩\". 밸런스는 봇 매치로 검증했다.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"폭발 구덩이: 포병, 로켓, 전차포가 운석에 구덩이를 파며, 그 안을 걷거나 주행할 수 있고 엄폐물로도 쓸 수 있다.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"보병용 3인칭 시점(V, 설정 기억; 휴대폰은 조작 메뉴)과 포탄이 떨어질 지점을 표시하는 부드러운 차량 카메라.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6은 \"🕘 게임 버전\" 메뉴에 남아 있어, 새 버전이 마음에 들지 않으면 돌아갈 수 있다.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"매치 전에 고르는 컨소시엄 / 스웜 진영, 폭발 구덩이, 3인칭 시점",
"and older: v7.6, v7.5, milestones v1–v7.0":"이전 버전: v7.6, v7.5, 이정표 v1–v7.0",
