"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"좌클릭 — 타격(누르고 있으면 강타) · 우클릭 — 방어 · Shift — 블링크 · Q — 수리검 · G — 순간이동",
