"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor 라디오: EDMITRY의 트랙 100곡 이상을 게임 안에서 — 📻 버튼(PC: 5번 키, [ ] — 트랙). 음악은 필요할 때 스트리밍되어 게임 용량을 늘리지 않으며, 볼륨과 자동 시작은 설정에서, 그리고 \"Spotify에서 듣기\" 링크도 있습니다.",
