"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Portal Meteor 라디오 켜기/끄기([ ] — 트랙, Shift+[ ] — 볼륨)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 오른쪽 — Portal Meteor 라디오: 전투 중에 EDMITRY의 음악이 흐릅니다.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor 라디오: 전투 중에 EDMITRY의 음악이 흐릅니다. [ ] — 트랙.",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor 라디오(EDMITRY): 볼륨",
"Radio: start by itself in battle":"라디오: 전투 중 자동 켜기",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"로보 닌자: 카타나를 든 사이보그. 병영에서 \"그림자 프로토콜\" 연구로 해금됩니다(메카 공장 필요). 알아서 적 구역으로 순간이동하고, 적을 베어 넘기며(피 대신 불꽃), 돌진과 수리검을 쓰고, 적 닌자와 결투를 벌입니다. 조종하면 AUTO 모드 또는 수동 조작이 가능합니다(휴대폰에서는 전용 버튼).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor 라디오: EDMITRY 트랙 103곡을 게임 안에서. 5번 키(키 변경 가능), 휴대폰에서는 ☰ → 설정 → 사운드. 볼륨과 \"전투 중 자동 켜기\"는 설정에서 조절하며, 폭발음과 무전 음성이 나올 때는 음악이 작아집니다.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"새 언어: 우즈베크어와 타지크어 — 완전 지원, 중국어·스페인어·포르투갈어 — 부분 지원. 메뉴의 \"새 대전\" 옆에 새 언어 선택이 추가되었습니다.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"휴대폰: \"아이콘 숨기기\" 👁이 남은 버튼을 오른쪽 가장자리의 깔끔한 세로 열로 모아 줍니다. 세로 모드에서 더는 겹치지 않으며, iPhone — 게임이 Safari 제스처와 충돌하지 않고, \"공유 → 홈 화면에 추가\"로 전체 화면 실행이 가능합니다.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1 기준: 모서리의 ☰ 메뉴(일시정지, 다시 시작, 훈련, 그래픽), 자동 Dendy 없음, 휴대폰의 ✋ 행동 버튼. v7.8.1과 v7.8은 \"🕘 게임 버전\" 메뉴에 남아 있습니다.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"로보 닌자, EDMITRY 라디오, 우즈베크어와 타지크어, 휴대폰·iPhone 편의성",
