"Carpet bombing":"융단 폭격",
"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"폭격기가 아군 기지 방향에서 진입해(전투 중에는 시선 방향을 따라) 80m 구간에 폭탄 10발을 투하합니다. 3.5초 후 폭격이 시작되며 구덩이를 남깁니다.",
"Napalm":"네이팜",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"반경 12m 화염 지대가 9초 동안 타오릅니다: 지속 피해, 제압, 연기. 2.5초 후 투하. 메탄에 불을 붙입니다.",
