"⚠ Rumbling underground: the Swarm is digging a tunnel! Breakthrough in ~10 s — be ready":"⚠ 지하에서 울리는 소리: 스웜이 터널을 파고 있습니다! 약 10초 후 돌파 — 대비하세요",
