"Quiet here — {0}: a unit closer to the fight":"조용해 — {0}: 전투에 더 가까운 유닛으로",
"You run faster along the strategist's green chevrons":"전략가의 초록 화살표를 따라가면 더 빨리 달려",
"{0} — mode: Strategist → Commander → Shooter":"{0} — 모드: 전략가 → 커맨더 → 슈터",
"{0} — turn off the AI strategist and command yourself":"{0} — AI 전략가를 끄고 직접 지휘",
"{0} — third-person view":"{0} — 3인칭 시점",
"{0} — reload early":"{0} — 미리 재장전해",
"Lots of hostiles — {0}: Reflex":"적이 많아 — {0}: 리플렉스",
"Enemy vehicle or structure — {0}: rocket":"적 차량이나 건물 — {0}: 로켓",
"Enemies bunched up — {0}: grenade":"적이 뭉쳐 있어 — {0}: 수류탄",
"Enemy cluster — {0}: strike at your aim":"적 밀집 — {0}: 조준 지점에 타격",
"Goal: destroy the enemy HQ and all its key buildings":"목표: 적 사령부와 모든 핵심 건물 파괴",
"60 minutes: destroy the enemy HQ or hold more points":"60분: 적 사령부를 파괴하거나 더 많은 지점을 점령해",
"Left thumb — move, right — look, red — fire":"왼쪽 엄지 — 이동, 오른쪽 — 시점, 빨간 버튼 — 사격",
"Mode button at the top right: tap — next, hold — pick":"오른쪽 위 모드 버튼: 탭 — 다음, 길게 — 선택",
"⇆ — next unit · ☰ — menu, clean screen, this card":"⇆ — 다음 유닛 · ☰ — 메뉴, 클린 스크린, 이 안내",
