"Hero quest":"영웅 퀘스트",
"Commander, their AA radar blinds our air. Take it down.":"커맨더, 저쪽 대공 레이더가 우리 공군의 눈을 가려. 날려버려.",
"Bring me a crystal from the Singing Vein — I will build something.":"노래하는 광맥에서 크리스탈 하나만 가져와 — 뭔가 만들어줄게.",
