"Capture the relay":"중계기 점령",
"HQ: the front is stuck. There is a chance — {0}.":"사령부: 전선이 막혔어. 기회가 있어 — {0}.",
"HQ: the front is stuck — an op is available":"사령부: 전선이 막혔어 — 작전 가능",
"enemy turrets silent for 2 min":"적 터렛 2분간 침묵",
"enemy map revealed for 60 s":"적 지도 60 s간 공개",
"Generator destroyed":"발전기 파괴됨",
"Relay captured":"중계기 확보",
"Enemy generator down! Their turrets are silent for two minutes.":"적 발전기 폭파! 적 터렛이 2분간 침묵해.",
"The relay is ours! The whole enemy map is visible for a minute.":"중계기는 우리 거야! 적 지도 전체가 1분간 보여.",
"Enemy sabotage: our turrets are down for 2 min":"적의 파괴 공작: 아군 터렛 2분간 정지",
"Enemy took the relay: they see us for 60 s":"적이 중계기 점령: 60 s간 우리가 노출돼",
"Sabotage! Our turrets are without power for two minutes.":"파괴 공작! 아군 터렛이 2분간 전원이 끊겼어.",
"The enemy took the relay — they see our whole map.":"적이 중계기를 점령했어 — 우리 지도 전체가 보여.",
"Intel: the enemy is going for our generator":"정찰: 적이 우리 발전기를 노리고 있어",
"Intel: the enemy is heading for the relay":"정찰: 적이 중계기로 향하고 있어",
"Warning! Enemy saboteurs are heading for our generator, {0}. Intercept!":"경고! 적 파괴 공작원이 우리 발전기로 가고 있어, {0}. 차단해!",
"Warning! The enemy is going to capture the relay, {0}. Stop them!":"경고! 적이 중계기를 점령하러 가고 있어, {0}. 막아!",
"Declined":"거절됨",
