"Help delivered":"지원 완료",
"Complete":"완료",
"helping your own":"아군 지원",
"thanks, you saved us!":"고마워, 살았어!",
"thanks, back to building!":"고마워, 마저 지을게!",
"thanks, we owe you!":"고마워, 신세 졌어!",
"take the second gun — let us ride":"두 번째 포에 타 — 한번 달려보자",
