"Living world: requests, hero quests, breakthrough ops":"살아 있는 세계: 아군 요청, 영웅 퀘스트, 전세 역전 작전",
"Living world":"살아 있는 세계",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"아군이 도움을 청하고 보상해주며, 영웅이 퀘스트를 주고, 길어진 전선은 작전으로 돌파해",
"A request":"아군 요청",
"Breakthrough":"전세 역전",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"아군이 가끔 도움을 청해: 무전 음성, \"요청\" 카드와 ✋ 표시. 분대가 제압당했어 — 근처의 적을 처치해. 보상: 기지에서 포드로 병사, 버기 짐칸의 총, 사수석 또는 궤도 엄호. 원하지 않으면 ✕ 또는 그냥 무시해.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"베테랑 정찰병 \"올빼미\"가 퀘스트를 제안해. Y — 수락(N — 거절). ★ 표시로 가서 경비병을 처치하고 조종사 옆에 3초간 머물러 — 그가 네 분대에 합류해.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"전선이 막혔어 — 사령부가 전세 역전 작전을 제안해. Y — 수락. 주변에 적이 없는 채로 중계기를 8초간 지켜: 적 지도가 60초간 공개돼. 발전기 — 적 포탑이 2분간 침묵해. 전략가 모드에서는 \"분대 지정\". 적도 같은 짓을 할 수 있어: ⚠를 주시해.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"아군이 도움을 청해: \"요청\" 카드와 ✋ 표시. 제압당한 분대 근처의 적을 처치하면 보상을 받아. ✕ — 건너뛰기.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"영웅 \"올빼미\"가 퀘스트를 제안해 — \"수락\"을 탭해. ★로 가서 경비병을 처치하고 조종사 옆에 머물러.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"전선이 막혔어 — \"수락\"을 탭하고 중계기를 8초간 지켜: 적 지도가 1분간 열려.",
"Pod redeploy from the base: {0} m — through the sky portal":"기지에서 포드로 재배치: {0} m — 하늘 포털을 통해",
"Pod away from the base! Hold on — exit over the target.":"기지에서 포드 출발! 꽉 잡아 — 목표 위로 나와.",
"Landed at the objective!":"목표 지점 강하 완료!",
