"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"강철 솜털이 달라붙었어 — 장갑을 초당 2씩 부식시켜. 전투 밖에서 3초간 가만히 서 있거나 공병을 찾아",
"An engineer brushed the fluff off":"공병이 솜털을 털어냈어",
