"1. Start a screen recording with your voice (PC — OBS, phone — the built-in screen recorder with mic) and turn on Feedback mode here.":"1. 음성이 들어가는 화면 녹화를 켜고(PC — OBS, 휴대폰 — 마이크가 켜진 기본 화면 녹화) 여기서 피드백 모드를 켜세요.",
"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. 플레이하면서 생각을 소리 내어 말하세요: 뭐가 불분명한지, 뭐가 거슬리는지, 뭐가 재밌는지. 화면 모서리에 버전, 시간, FPS가 표시되어 녹화와 메모를 맞춰 볼 수 있어요.",
