"Unlock the Strategist mode: look from above and give orders to the whole army.":"전략가 모드를 해금하세요: 위에서 내려다보며 군대 전체에 명령을 내립니다.",
"Want to lead one squad?":"분대를 이끌어 보고 싶나요?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"커맨더 모드를 해금하세요: 카메라가 분대 위에 있고, 탭으로 이동할 곳을 지정합니다.",
"Yes":"예",
"Later":"나중에",
"You run and shoot yourself. That is how you have played so far.":"직접 뛰어다니며 사격합니다. 지금까지 해 온 방식이에요.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"위에서 내려다보며 군대 전체를 지휘합니다: 기지를 짓고 분대를 보내세요. 군대는 당신이 없어도 알아서 싸웁니다.",
"You lead one squad: the camera is above it, tap the ground to move.":"분대 하나를 이끕니다: 카메라가 분대 위에 있고, 땅을 탭하면 이동합니다.",
"The mode button is at the top right: tap for the next mode.":"모드 버튼은 오른쪽 위에 있어요: 탭하면 다음 모드로 넘어갑니다.",
