"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"힌트가 접혔어요 — \"?\"를 누르면 다시 열립니다. 강의 나가기: ☰ → \"강의 나가기\"",
"◎ precise":"◎ 정밀",
