"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"커맨더 모드, 진영 보스, 살아 있는 운석(지형, 바이옴, 날씨, 이상 현상, 동식물), 살아 있는 월드; 더 빨라진 성능, 게임패드, 태블릿, 백과사전, 피드백 모드, 휴대폰용 간단 인터페이스",
"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"버튼 하나로 전환되는 세 가지 모드: 사수(직접 전투), 새로운 커맨더(분대 하나를 지휘, 유닛 종류마다 능력 4개), 전략가. 휴대폰에서는 간단 인터페이스로 버튼이 줄고, 전투를 진행하면서 모드가 해금됩니다.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"살아 있는 운석: 바위, 능선, 메사 속 격납고, 용암·얼음·메탄 호수, 세 가지 바이옴, 지역별 날씨, 새로운 이상 현상과 토착 동식물.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"진영이 서로 다르게 플레이됩니다: 스웜은 터널을 파고 재생하며, 컨소시엄은 장벽을 세우고 수리합니다. 12분부터 \"Bastion\"과 \"Reaper\" 보스가 등장하며, 아군 보스에게 빙의할 수 있어요.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"살아 있는 월드: 아군 보병이 무전으로 도움을 요청하고(보상 있음), 영웅이 임무를 주며, 전선이 정체되면 \"전세 역전\" 작전이 발동합니다. 캡슐, 보급 상자, 타격이 기지에서 하늘 포털을 통해 출발합니다.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"더 빨라졌습니다(프레임당 비용 최대 2배 절감), 모든 모드에서 게임패드 지원, 태블릿 레이아웃, 게임 속 모든 것을 담은 백과사전, 피드백 모드 — 키 하나로 스크린샷이 포함된 메모를 남길 수 있습니다.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"새로운 텍스트는 모두 우즈베크어, 타지크어, 중국어, 스페인어, 포르투갈어, 히브리어로 번역되었습니다. v7.9의 닌자와 무전은 그대로이며, v7.9는 \"🕘 게임 버전\" 메뉴에 있습니다.",
"New in v8.15":"v8.15 새 기능",
"NEW IN v8.15":"v8.15 새 기능",
